type CallReplay = {
	// selector or full request bytes the call payload must contain.
	request: Uint8Array
	response: Uint8Array
}

// zoneASolanaReplay is DON 1 (workflow_1_zone-a, configCount 21) on the production registry, recorded 2026-11-04.
